package com.smeal.controller; import com.smeal.dto.*; import com.smeal.service.AuthService; import jakarta.validation.Valid; import java.util.Map; import org.springframework.http.HttpHeaders; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/register") public AuthResponseDTO register(@Valid @RequestBody AuthRequestDTO r){return auth.register(r);}@PostMapping("/login") public AuthResponseDTO login(@Valid @RequestBody AuthRequestDTO r){return auth.login(r);}@PostMapping("/refresh") public AuthResponseDTO refresh(@RequestBody Map<String,String> r){return auth.refresh(r.get("refreshToken"));}@PostMapping("/logout") public Map<String,Object> logout(@RequestHeader(value=HttpHeaders.AUTHORIZATION,required=false)String h,@RequestBody(required=false)Map<String,String> body){auth.logout(body==null?null:body.get("refreshToken"),h);return Map.of("success",true,"message","Logged out");}}
